const raw = $input.first()?.json ?? {};
const body = raw.body ?? raw;
const theme = String(body.theme ?? '').trim();
const postCount = Math.min(6, Math.max(3, Number(body.postCount) || 4));
const targetAudience = String(body.targetAudience ?? '').trim();
const clientId = String(body.client_id ?? '').trim();
if (!theme) throw new Error('theme is verplicht');
if (!clientId) throw new Error('client_id is verplicht');

return {
  json: {
    theme,
    postCount,
    targetAudience,
    client_id: clientId,
  },
};

const inputJson = $input.first().json;
let rawContent = '';

if (inputJson.content && Array.isArray(inputJson.content)) {
  rawContent = inputJson.content
    .filter((b) => b.type === 'text' || b.text)
    .map((b) => b.text || '')
    .join('');
} else if (inputJson.message?.content) {
  const msg = inputJson.message.content;
  rawContent = Array.isArray(msg) ? msg.map((b) => b.text || '').join('') : String(msg);
} else if (inputJson.text) {
  rawContent = inputJson.text;
} else {
  rawContent = '{}';
}

let cleanJson = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    campaignTitle: 'Fout bij plannen',
    posts: [],
    error: 'JSON parse fout: ' + e.message,
    generatedAt: new Date().toISOString(),
  };
}

if (!parsed.generatedAt) {
  parsed.generatedAt = new Date().toISOString();
}

if (!Array.isArray(parsed.posts)) {
  parsed.posts = [];
}

return [{ json: parsed }];

const prep = $('Prepare Prompt').first().json;
const client = $input.first().json;

if (!client || !client.id) {
  throw new Error('Geen client gevonden voor client_id: ' + prep.client_id);
}

const audienceLine = prep.targetAudience
  ? `Doelgroep: ${prep.targetAudience}.`
  : 'Doelgroep: algemeen B2B LinkedIn-publiek.';

// Build strategy context from DB fields
const strategyContext = [
  client.archetype ? `Archetype: ${client.archetype}` : '',
  client.archetype_traits ? `Archetyp-kenmerken: ${client.archetype_traits}` : '',
  client.adversary ? `Tegenstander (adversary): ${client.adversary}` : '',
  client.brand_goal ? `Merkdoel: ${client.brand_goal}` : '',
  client.writing_guide ? `Schrijfwijzer:\n${client.writing_guide}` : '',
].filter(Boolean).join('\n');

const userPrompt = `Plan een LinkedIn-contentcampagne voor ${client.name}.

MERKSTRATEGIE:
${strategyContext}

${audienceLine}
Probleem/thema (1 zin): ${prep.theme}
Aantal posts: ${prep.postCount}

Genereer een campagneschema met ${prep.postCount} posts verspreid over opeenvolgende weken (week 1 t/m ${prep.postCount}).
Varieer formaten: storytelling, steps (3-stappen), opinion, data (cijfers + verhaal).
Elke post heeft een kernboodschap (theme), invalshoek (angle — kies uit: archetype, adversary, general — passend bij de merkstrategie), hook (openingszin), format, tags (3-5 hashtags zonder #).
Post 4 of later mag readyToPublish false zijn als productiedata ontbreekt — geef dan holdReason.

Antwoord ALLEEN met valid JSON (geen markdown):
{
  "campaignTitle": "...",
  "posts": [
    {
      "postNumber": 1,
      "week": 1,
      "theme": "...",
      "angle": "archetype|adversary|general",
      "hook": "...",
      "format": "storytelling",
      "tags": ["tag1", "tag2"],
      "readyToPublish": true,
      "holdReason": ""
    }
  ],
  "generatedAt": "ISO-8601"
}`;

return {
  json: {
    theme: prep.theme,
    postCount: prep.postCount,
    client_id: prep.client_id,
    client_name: client.name,
    claudeBody: {
      model: 'claude-sonnet-4-6',
      max_tokens: 4096,
      system: 'Je bent campagneplanner voor LinkedIn B2B-content. Je kent de merkstrategie van de klant en past die toe bij het plannen van de campagne. Output uitsluitend JSON volgens het gevraagde schema. Geen markdown fences.',
      messages: [{ role: 'user', content: userPrompt }],
    },
  },
};
